            "seen_in_history_but_not_booked_into": "Sedda i historiken men inte bokförda i siffrorna ovan ({{skippedTotal}} operationer) — sociala/styrningsåtgärder utan saldopåverkan, inkomst som redan räknats vid inlösen, eller rörelser som avräknas vid en senare utförande:",
