            "deductions_optional_losses_you_carried_forward_f": "Avdrag — valfritt. Förluster du framfört från tidigare år kvittas mot årets vinster; fribeloppssiffran anger hur mycket av landets schablonavdrag du redan utnyttjat på annat håll. Tillämpas automatiskt där din jurisdiktion erbjuder dem.",
            "send_labels_are_assigned_in_the_classify": "Sändningsetiketter tilldelas i steget Klassificera och sparas per konto. Massredigera dem i ett kalkylblad om du föredrar det:",
            "say_what_each_outbound_send_was_so": "Ange vad varje utgående sändning var, så att den beskattas rätt. Varje sändning behandlas som en skattepliktig försäljning om du inte etiketterar den — att markera din egen börs, dina egna plånböcker, gåvor eller donationer ändrar skatten. Etiketterna sparas till nästa gång. Fortsätt tillämpar dem och räknar om rapporten.",
            "nothing_to_classify_no_outbound_transfers_to": "Inget att klassificera — inga utgående överföringar till tredje part hittades i din historik. Fortsätt för att granska och exportera.",
            "opening_balances_are_tokens_you_already_held": "Ingående saldon är tokens du redan innehade före kontots första registrerade operation. Ange dem så att äldre avyttringar får ett verkligt omkostnadsbelopp i stället för en vinst med nollkostnad (överdriven). Kostnaden är det totala du betalade för den ingående mängden, i {{cur}}.",
            "generate_a_record_of_your_on_chain": "Generera en översikt över din aktivitet på kedjan under ett datumintervall, klassificerad för skatt av FairFlow-motorn. Fyll i alternativen, klassificera dina sändningar och exportera sedan som PDF, CSV eller JSON.",
            "values_use_the_wallets_current_price_a": "Värdena använder plånbokens aktuella {{fiat}}-pris — en enda ögonblicksbild utan historiskt flöde, så innehavstotalen är korrekt medan realiserade vinster är ungefärliga (en avyttrings ersättning och omkostnadsbelopp delar samma aktuella pris). Koppla in en historisk oracle-/Kursliste-källa för exakta vinster.",
