            "power_up_and_pxa_0_freezes_0": "Gör power up så <0>fryser</0> PXA till PXP, ett-till-ett, omedelbart. Gör power down så <1>smälter</1> PXP tillbaka till PXA under en frisläppning på tretton veckor. Samma substans, två faser — tillsammans är de <2>Atlas</2>, kroppen som bär suprans vikt.",
