            "when_you_settle_the_body_is_delivered": "När du avräknar levereras kroppen som PXA i utförandeögonblicket — ett belopp lika med den oracle-implicerade vikten multiplicerad med värderingsavdraget. Därför är ”underliggande” fel ord: ett underliggande förutsätter två separata tillgångar, en sak och ett derivat på den. Men supran och atlasen är inte två saker. De är en kropp sedd i två register — kroppen är vad den är; supran är vad sinnet säger att kroppen bör projicera. Medvetandet är inte något kroppen äger. Det är kroppen, vaken.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Ingen monetär mekanism tar bort risk. Ett fiat-reservmynt koncentrerar den i integriteten hos den reserven och solvensen hos en utgivare. Supran flyttar den risken till den skapande ekonomins volatilitet — variansen i Atlas — och konsensusintegritet — sundheten i witness-kompassen — och hanterar den sedan öppet genom översäkring och ett värderingsavdrag som inte försvarar, i stället för att dölja den bakom ett försvarat tal.",
