            "keep_them_in_a_safe_place_and": "Förvara dem på en säker plats och dela dem aldrig. Vårt team kommer aldrig att be dig om dina privata nycklar.",
            "private_key_on_clipboard_warning": "Privat nyckel kopierad. Urklippet kan läsas av andra appar och kan synkroniseras bort från den här enheten — klistra in den nu; den skrivs över om 30 sekunder.",
            "could_not_copy": "Kunde inte kopiera till urklipp.",
            "permissions_use_your_key_to": "<b>{{title}}-behörigheter</b><br>Använd din {{title}} för att:",
            "effective_in_strong_strong_day": "— träder i kraft om <strong>%n</strong> {{{_plurals.day}}}",
            "adding_a_password_provides_extra_security_especi": "Att lägga till ett lösenord ger extra säkerhet, särskilt för kortare seed phrases.",
            "you_are_about_to_request_a_change": "Du är på väg att begära ett byte av återställningskonto för <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Utse ett betrott konto — en medgrundare, en systerplånbok du kontrollerar, eller en kontakt du kan nå utanför kedjan — som kan hjälpa dig att återfå åtkomsten om din owner-nyckel någonsin går förlorad eller komprometteras. Återställningsflödet använder din owner-nyckelhistorik, så återställningskontot kan på egen hand aldrig ta över ditt konto: det kan bara hjälpa dig att återställa det. Ändringar träder i kraft efter ett väntefönster på 30 dagar.",
            "strong_30_day_waiting_period_strong_changing": "<strong>30 dagars väntetid.</strong> Att byta återställningskonto sker inte omedelbart. En ny begäran träder i kraft <strong>30 dagar efter sändning</strong>; fram till dess gäller det nuvarande återställningskontot. Att sända igen under väntefönstret ersätter den väntande begäran. Att sätta tillbaka det till det nuvarande värdet avbryter en väntande ändring.",
            "pick_someone_you_trust_personally_a_co": "Välj någon du litar på personligen — en medgrundare, ett systerkonto du kontrollerar, eller en plånbok vars ägare du kan nå utanför kedjan.",
            "generate_a_fresh_seed_phrase_to_derive": "Generera en färsk seed phrase för att härleda nya nycklar till ditt konto. Din seed phrase är huvudnyckeln till alla dina kontonycklar — förvara den säkert och dela den aldrig. Owner-nyckeln används för att signera nyckeluppdateringstransaktionen när du bekräftar nedan.",
            "this_will_strong_cancel_any_pending_recovery": "Detta kommer att <strong>avbryta varje väntande byte av återställningskonto</strong> genom att på nytt sända samma värde som ditt nuvarande återställningskonto. Den väntande 30-dagarsbegäran ersätts; det nuvarande återställningskontot gäller hela tiden.",
            "once_broadcast_the_chain_will_create_a": "När det har sänts skapar kedjan en väntande begäran som träder i kraft om <strong>30 dagar</strong>. Ditt nuvarande återställningskonto (<0>@{{currentRecovery}}</0>) gäller fram till dess. Du kommer att bli ombedd att ange din <strong>owner-nyckel</strong>.",
            "posting_description_1": "Denna nyckel bör användas för sociala åtgärder, som att posta, kommentera och rösta. Nyckeln har en begränsad uppsättning behörigheter och kan inte användas för monetära åtgärder.",
            "posting_description_2": "Använd denna nyckel för att logga in på Pixa-baserade sociala nätverk som Pixagram.com. Förvara nyckeln säkert.",
            "active_description_1": "Denna nyckel har ytterligare behörigheter för mer känsliga monetära åtgärder, som att överföra och växla tokens.",
            "active_description_2": "När du utför en plånboksrelaterad åtgärd kan du bli ombedd att autentisera med din Active-nyckel. Ange endast din Active Key i appar du litar på, eftersom vem som helst med tillgång till denna nyckel kan ta dina tokens.",
            "owner_description_1": "Owner-nyckeln krävs för att ändra de andra nycklarna. Den har ytterligare behörigheter för att återställa ditt konto eller ändra dina andra nycklar. Det är den viktigaste nyckeln och bör förvaras säkert offline.",
            "memo_description_1": "Memo-nyckeln är lite av en avvikare. Det enda Memo Key kan göra är att kryptera och dekryptera privata meddelanden som skickas via blockkedjan.",
