            "the_price_feed_for_the_pixasupra_versus": "Prisflödet för PixaSupra mot Pixa ligger på cirka 1:57. Prisflödet används för att balansera incitamentet mellan valutorna. PixaSupra och Pixa söker en jämvikt: det bör finnas <b>3,3 gånger fler</b> flytande tokens än oracle-refererade, så att PixaSupra håller sig under 30 % av Pixa-kapitaliseringen. Det betyder att vi nu har en marginal på <b>3,7×</b> för att korrigera utbudet: faller priset på Pixa så mycket träder värderingsavdragsregeln in.",
