            "hide_no_problem_and_promise_no_more": "Dölj inget problem, och lova inte mer än vad som kan hållas.",
            "what_does_not_break_the_network_strengthens": "Det som inte knäcker nätverket stärker det.",
            "to_create_and_to_curate_is_worth": " Att skapa och att kuratera är värt mer än att äga i tystnad; de som dyker upp är Pixas levande substans, och det byggs först och främst för dem.",
            "and_most_beautiful_of_all_are_the": " — och skönast av allt är händerna som gör dem. Hedra skaparen i verket.",
            "and_only_then_refine_your_work_to": " och förfina först därefter ditt verk så att det stiger. Glädjen i hantverket kommer först; ambitionen för verket kommer sedan.",
            "for_greatness_lies_in_the_highest_to": " för storheten ligger i det högsta. Att posta ofta är bra; att posta väl är större.",
            "but_let_your_highest_goal_be_their": " men låt ditt högsta mål vara deras mening — för det som bär mening är det som består.",
            "for_conquest_is_never_accomplished_no_milestone": " för erövringen fullbordas aldrig. Ingen milstolpe är en topp; verket blir aldrig färdigt.",
            "lift_the_smallest_accounts_as_you_climb": " Lyft de minsta kontona medan du stiger, för dagens småfisk är morgondagens mästare.",
            "but_treat_it_sometimes_as_an_impostor": " men behandla den ibland som en bedragare — och var alltid rättvis. Det mängden älskar är inte alltid det bästa; förbli din egen domare.",
            "to_dislike_is_your_right_and_to": " Att inte tycka om är din rätt, och att döma är inte att censurera; ge downvote eller gå förbi varje verk som inte rör dig.",
            "a_community_is_known_by_how_it": " En gemenskap känns igen på hur den skyddar de sårbara; vänd din styrka mot att skapa, aldrig mot en annan.",
            "let_every_tool_serve_the_creator_and": " Låt varje verktyg tjäna skaparen och aldrig träda i dennes ställe.",
            "in_your_work_and_in_your_dealings": " i ditt verk och i dina mellanhavanden, för ärlighet är klippan som all styrka byggs på.",
            "contribute_to_it_not_for_today_or": " Bidra till det, inte för i dag eller för i går, utan för all framtid.",
            "it_funds_development_and_the_protocol_the": " — den finansierar utvecklingen och protokollet. Marknadsföringen av Pixa tillhör dess människor, aldrig dess skattkammare.",
            "the_foundation_stewards_it_does_not_rule": " Stiftelsen förvaltar; den härskar inte. Det som byggs här tillhör alla som bygger det.",
            "should_governance_ever_fail_the_community_may": " Skulle styrningen någonsin svikta, får gemenskapen bära verket vidare någon annanstans, i sin helhet.",
            "what_is_true_is_said_plainly_even": " Det som är sant sägs rakt ut, även när en bekväm fiktion vore lättare.",
            "we_endure_by_bending_to_the_storm": " Vi består genom att böja oss för stormen, inte genom att låtsas att ingen kommer.",
            "uniquely_we_are_free_together_we_are_stronger": "Var för sig är vi fria; tillsammans är vi starkare.",
            "these_principles_are_the_foundation_of_pixa": "Dessa principer är grunden för Pixa och för den gemenskap vi bygger på den — ärlig, rättvis, varaktig och enad. Protokollet förbjuder bara det som det måste; allt gott bortom den gränsen är den karaktär vi väljer. Detta är den karaktären: andan i vilken vi skapar, sättet vi behandlar varandra på och måttstocken vi mäter oss själva med. De binder ingen med tvång, och ändå binder de oss alla.",
            "free_in_our_hands_united_in_our_purpose": "Fria i våra händer, enade i vårt syfte — <0>vi bygger för all framtid.</0>"
