            "anyone_who_views_or_interacts_with_the": "Var och en som tittar på eller interagerar med konstverket men inte äger den tillhörande NFT:n.",
            "legal_agreement": "Juridiskt avtal",
            "this_nft_license_agreement_the_agreement": "Detta licensavtal för NFT (”Avtalet”) fastställer de anpassningsbara villkor enligt vilka skaparen (nedan kallad ”Upphovspersonen”) beviljar vissa rättigheter till köparen (”Innehavaren”) av icke-fungibla tokens (NFT:er) som är kopplade till en specifik samling digitala konstverk (”Samlingen”). Syftet med Avtalet är att erbjuda ett flexibelt, transparent och rättvist licensramverk som kan anpassas till olika användningsområden, affärsmodeller och konstnärliga avsikter, samtidigt som det säkerställer att Upphovspersonens ideella rättigheter förblir intakta och fullt ut bevarade. Strukturen är särskilt utformad för NFT-skapare som vill ge innehavarna av sina digitala tillgångar skräddarsydda användningsrättigheter, vilket möjliggör en rad olika interaktioner med och former av utnyttjande av konstverket beroende på de preferenser Upphovspersonen har valt.",
            "ownership_and_moral_rights": "Äganderätt och ideella rättigheter",
            "the_author_is_and_shall_remain_the_sole": "Upphovspersonen är och ska förbli ensam och exklusiv ägare till alla immateriella rättigheter till de underliggande konstverken och allt tillhörande innehåll som är kopplat till NFT:erna. Upphovspersonen behåller alla ideella rättigheter, inklusive rätten att anges som skapare och att motsätta sig varje förvanskning, stympning eller annan ändring av verket som skulle kränka dennes heder eller anseende. Dessa ideella rättigheter kan inte överlåtas och gäller för evigt, och de ska respekteras av alla Innehavare och tredje parter. Detta Avtal ska inte tolkas som ett avstående från eller en begränsning av sådana rättigheter.",
            "license_options_for_the_holder": "Licensalternativ för Innehavaren",
            "the_holder_of_an_nft_is_granted_a_non": "Innehavaren av en NFT beviljas en icke-exklusiv, världsomfattande och royaltyfri licens att använda det digitala konstverk som är kopplat till NFT:n, men endast i den utsträckning som Upphovspersonen uttryckligen tillåter nedan. Licensen är strikt knuten till den specifika NFT som innehas och överlåts automatiskt vid vidareförsäljning. Syftet med detta avsnitt är att låta Upphovspersonen välja omfattningen av de rättigheter som beviljas varje Innehavare och därigenom erbjuda juridisk tydlighet och kreativ flexibilitet för båda parter. För varje angiven rättighet kan Upphovspersonen ange om Innehavaren får utöva den.",
